slots.VIEW:
SIM = {
  duration: 4,
  bodies: [
    { id: "rod", at: function (s) { const b = s.rod; return [b.cx ?? b.x, b.cy ?? b.y]; } }
  ],
  phases: [{ t0: 0, t1: 2 }, { t0: 2, t1: 4 }],
};

slots.stateAt:
const V0 = 1;
const VMAX = 0.5;
const TAU = 0.65;
const T_OPEN = 2;
const X0 = 3.8;
const NORM = 1 - Math.exp(-T_OPEN / TAU);
const X_OPEN = X0 + (VMAX / NORM) * (T_OPEN + TAU * (Math.exp(-T_OPEN / TAU) - 1));
const I_OPEN = VMAX;
const state = {};
const tt = Math.max(0, Math.min(t, 4));
let x, v, sw, I, Uc;
if (tt < T_OPEN) {
  v = VMAX * (1 - Math.exp(-tt / TAU)) / NORM;
  x = X0 + (VMAX / NORM) * (tt + TAU * (Math.exp(-tt / TAU) - 1));
  sw = 1;
  I = v;
  Uc = 0;
} else {
  const dt = tt - T_OPEN;
  v = VMAX;
  x = X_OPEN + v * dt;
  sw = 0;
  I = I_OPEN * Math.exp(-dt / 0.35);
  Uc = 0.25 * V0 * (1 - Math.exp(-dt / 0.35));
}
state.rod = { x: x, y: 1.7, type: 'conductor_rod', cx: x, cy: 1.7, w: 0.18, h: 1.0 };
state.v = v;
state.S = sw;
state.I = I;
state.Uc = Uc;
return state;

slots.drawFrame:
const rod = state.rod;
const top = 2.2;
const bot = 1.2;
const left = 0.8;

// 导轨与左侧电路
Draw.line([left, top], [9.0, top]);
Draw.line([left, bot], [9.0, bot]);
Draw.line([left, bot], [left, top]);

// 定值电阻 R
Draw.box([2.0, top], 0.8, 0.16);

// 开关 S（在左侧竖线上）
const sy = 1.72;
if (state.S) {
  Draw.line([left, bot], [left, top]);
} else {
  Draw.line([left, bot], [left, sy - 0.12]);
  Draw.line([left, sy + 0.12], [left, top]);
  Draw.line([left, sy - 0.12], [left + 0.18, sy + 0.18]);
}

// 电容 C 支路
Draw.line([left, top], [1.25, top]);
Draw.line([left, bot], [1.25, bot]);
Draw.line([1.25, top], [1.25, 1.62]);
Draw.line([1.25, bot], [1.25, 1.50]);
Draw.line([1.06, 1.62], [1.44, 1.62]);
Draw.line([1.06, 1.50], [1.44, 1.50]);

// 磁场区（叉号）
Draw.fieldDots({ x: 3.2, y: 1.3, w: 5.4, h: 0.8 }, { nx: 9, ny: 4, symbol: 'cross' });

// 金属棒
Draw.box([rod.cx, rod.cy], rod.w, rod.h);

// 外力（向右）
Draw.arrow([rod.cx, rod.cy], [0.7, 0], { category: 'force', mag: 0.7 });

slots.readouts:
return [
  { key: 'v', label: '金属棒速度', value: state.v, unit: 'v0' },
  { key: 'x', label: '金属棒位置', value: state.rod.x, unit: 'm' },
  { key: 'I', label: '感应电流', value: state.I, unit: 'I0' },
  { key: 'Uc', label: '电容电压', value: state.Uc, unit: 'BLv0' },
];
